-- Metadata only. No user content, URLs, identifiers or secret values.
select jsonb_build_object(
 'public_tables', (select count(*)=2 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('life_naver_subscriptions','life_naver_items') and c.relrowsecurity),
 'private_tables', (select count(*)=2 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='haedo_naver_private' and c.relname in ('runtime','receipts') and c.relrowsecurity),
 'owner_read_policies', (select count(*)=2 from pg_policies where schemaname='public' and tablename in ('life_naver_subscriptions','life_naver_items') and cmd='SELECT' and roles=array['authenticated']::name[] and qual like '%owner_id%' and qual like '%auth.uid()%'),
 'no_client_writes', not has_table_privilege('authenticated','public.life_naver_subscriptions','INSERT,UPDATE,DELETE') and not has_table_privilege('authenticated','public.life_naver_items','INSERT,UPDATE,DELETE'),
 'no_anon_tables', not has_table_privilege('anon','public.life_naver_subscriptions','SELECT,INSERT,UPDATE,DELETE') and not has_table_privilege('anon','public.life_naver_items','SELECT,INSERT,UPDATE,DELETE'),
 'owner_select', has_table_privilege('authenticated','public.life_naver_subscriptions','SELECT') and has_table_privilege('authenticated','public.life_naver_items','SELECT'),
 'owner_api_acl', has_function_privilege('authenticated','public.life_naver_save(uuid,text,bigint,boolean)','EXECUTE') and has_function_privilege('authenticated','public.life_naver_list(uuid,integer,jsonb)','EXECUTE') and not has_function_privilege('anon','public.life_naver_save(uuid,text,bigint,boolean)','EXECUTE') and not has_function_privilege('anon','public.life_naver_list(uuid,integer,jsonb)','EXECUTE'),
 'worker_api_acl', has_function_privilege('service_role','public.life_naver_claim(integer,uuid,uuid)','EXECUTE') and has_function_privilege('service_role','public.life_naver_finish(uuid,uuid,bigint,jsonb,text)','EXECUTE') and has_function_privilege('service_role','public.life_naver_ready()','EXECUTE') and not has_function_privilege('authenticated','public.life_naver_claim(integer,uuid,uuid)','EXECUTE') and not has_function_privilege('authenticated','public.life_naver_finish(uuid,uuid,bigint,jsonb,text)','EXECUTE') and not has_function_privilege('anon','public.life_naver_ready()','EXECUTE'),
 'public_invoker_wrappers', (select count(*)=5 and bool_and(not p.prosecdef and p.proconfig=array['search_path=pg_catalog']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('life_naver_save','life_naver_list','life_naver_claim','life_naver_finish','life_naver_ready')),
 'private_definer_guard_paths', (select count(*)=5 and bool_and(p.prosecdef and p.proconfig=array['search_path=pg_catalog']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='haedo_naver_private' and p.proname in ('save','list','claim','finish','ready')),
 'runtime_disabled', not coalesce((select ready from haedo_naver_private.runtime where singleton),true)
);
